UPDATE apr04_appr_step
   SET apr04_step_status_cd = CAST(#{statusCode} AS varchar)
     , apr04_note           = #{note}
     , apr04_reject_reason  = #{rejectReason}
     , apr04_appr_date      = f_sysdate()
     , apr04_appr_emp_id    = #{apprEmpId}
     , apr04_sign_id        = CASE WHEN CAST(#{statusCode} AS varchar) = '20'
                                   THEN ( SELECT emp60_sign_id
                                            FROM emp60_sign
                                           WHERE emp60_person_id = #{apprEmpId}
                                             AND COALESCE(emp60_use_yn, 'false') = 'true'
                                           LIMIT 1 )
                                   ELSE NULL END
 WHERE apr04_appr_id      = #{apprId}
   AND apr04_step_emp_id  = #{stepEmpId}
   AND apr04_step_type_cd = #{stepTypeCode}
   AND apr04_seq          = #{seq}

UPDATE apr04_appr_step
   SET apr04_step_status_cd = CAST(#{statusCode} AS varchar)
     , apr04_note           = #{note}
     , apr04_reject_reason  = #{rejectReason}
     , apr04_appr_date      = f_sysdate()
     , apr04_appr_emp_id    = #{apprEmpId}
     , apr04_sign_id        = CASE WHEN CAST(#{statusCode} AS varchar) = '20'
                                   THEN ( SELECT emp60_sign_id
                                            FROM emp60_sign
                                           WHERE emp60_person_id = #{apprEmpId}
                                             AND COALESCE(emp60_use_yn, 'false') = 'true'
                                           LIMIT 1 )
                                   ELSE NULL END
 WHERE apr04_appr_id = #{apprId}
   AND apr04_seq     = #{seq}

UPDATE apr01_appr
   SET apr01_status_cd = #{statusCode}
     , apr01_stamp_seq = #{stampSeq}
 WHERE apr01_appr_id = #{apprId}

UPDATE apr04_appr_step
   SET apr04_step_status_cd = '10'
     , apr04_reject_reason  = ''
     , apr04_appr_date      = NULL
     , apr04_appr_emp_id    = #{empId}
 WHERE apr04_appr_id     = #{apprId}
   AND apr04_step_emp_id = #{empId}
